package com.nook.widgets;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.text.*;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;

public final class ExtraOptions {
    private ExtraOptions(){}
    private static EditText field(Activity a,LinearLayout parent,JSONObject config,String key,String label,boolean number,boolean secret,Runnable refresh){parent.addView(Ui.text(a,label,12,Ui.MUTED));EditText input=new EditText(a);input.setTextColor(Ui.TEXT);input.setHintTextColor(Ui.MUTED);input.setHint(label);input.setSingleLine(true);input.setText(config.has(key)?config.optString(key):"");input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(secret?160:300)});if(secret)input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);else if(number)input.setInputType(InputType.TYPE_CLASS_NUMBER);parent.addView(input);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int start,int before,int count){if(number){try{ExtraData.put(config,key,Math.max(0,Math.min(1000000,Integer.parseInt(s.toString()))));}catch(NumberFormatException e){config.remove(key);}}else ExtraData.put(config,key,s.toString());refresh.run();}});return input;}
    public static void chooseApp(Activity a,java.util.function.Consumer<String> chosen){List<ResolveInfo> apps=a.getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);apps.sort(Comparator.comparing(v->v.loadLabel(a.getPackageManager()).toString(),String.CASE_INSENSITIVE_ORDER));String[] labels=new String[apps.size()];for(int n=0;n<labels.length;n++)labels[n]=apps.get(n).loadLabel(a.getPackageManager()).toString();new AlertDialog.Builder(a).setTitle("Choose an installed app").setItems(labels,(d,n)->chosen.accept(apps.get(n).activityInfo.packageName)).setNegativeButton("Cancel",null).show();}
    public static void add(Activity a,LinearLayout page,String kind,JSONObject config,Runnable refresh,java.util.function.BiConsumer<Integer,Intent> chooseFile){
        if(kind.equals("buds")){BudsOptions.add(a,page,config,refresh);return;}
        Ui.gap(page,12);
        if(kind.equals("tracker")){String[] keys={"activity","water","reading","steps","sleep","medications"},names={"Activity rings · manual log","Water · manual log","Reading · pages read","Steps · manual log","Sleep · minutes recorded","Medication · manual check-in"};Spinner type=new Spinner(a);type.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));int selected=Math.max(0,Arrays.asList(keys).indexOf(config.optString("trackerType","activity")));type.setSelection(selected);page.addView(type);type.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int n,long id){if(!config.optString("trackerType","activity").equals(keys[n])){ExtraData.put(config,"trackerType",keys[n]);ExtraData.put(config,"daily",!keys[n].equals("reading")&&!keys[n].equals("sleep"));refresh.run();}}});page.addView(Ui.text(a,"These are your own logs. They do not read Apple Health, Samsung Health, medications, or a pedometer automatically. Set your own targets; no target is prescribed.",12,Ui.MUTED));field(a,page,config,"trackerName","Custom tracker heading",false,false,refresh);field(a,page,config,"unit","Unit (ml, pages, steps, minutes…)",false,false,refresh);for(int n=0;n<3;n++){field(a,page,config,"amount"+n,"Recorded amount "+(n+1),true,false,()->{ExtraData.put(config,"trackedDay",java.time.LocalDate.now().toString());refresh.run();});field(a,page,config,"target"+n,"Your target "+(n+1)+" (optional)",true,false,refresh);}field(a,page,config,"increment","Quick-button increment",true,false,refresh);Switch daily=new Switch(a);daily.setText("Reset this log each day");daily.setTextColor(Ui.TEXT);daily.setChecked(config.optBoolean("daily",true));page.addView(daily);daily.setOnCheckedChangeListener((b,on)->{ExtraData.put(config,"daily",on);refresh.run();});}
        else if(kind.equals("files")){page.addView(Ui.text(a,"Pick individual files. Only those document grants are retained; Nook does not scan your storage.",12,Ui.MUTED));for(int n=0;n<3;n++){int slot=n;page.addView(Ui.button(a,"Choose file "+(n+1),Ui.SURFACE,Ui.ACCENT,()->chooseFile.accept(slot,new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION))));}}
        else if(kind.equals("bookmarks")||kind.equals("maps")){for(int n=0;n<3;n++){field(a,page,config,"name"+n,"Name "+(n+1),false,false,refresh);field(a,page,config,kind.equals("maps")?"destination"+n:"url"+n,kind.equals("maps")?"Destination address":"Web address (https://…)",false,false,refresh);}page.addView(Ui.text(a,kind.equals("maps")?"Opens directions in Google Maps or your browser. Traffic, location and ETA are provided there; no fabricated ETA is shown here.":"Saved links open in your browser when tapped.",12,Ui.MUTED));}
        else if(kind.equals("shortcuts")){for(int n=0;n<3;n++){int slot=n;page.addView(Ui.button(a,"Choose app "+(n+1),Ui.SURFACE,Ui.ACCENT,()->chooseApp(a,name->{ExtraData.put(config,"package"+slot,name);refresh.run();})));}}
        else if(kind.equals("news")){EditText sourceName=field(a,page,config,"feedName","Source name",false,false,refresh);EditText sourceUrl=field(a,page,config,"feedUrl","RSS or Atom feed URL (HTTPS)",false,false,refresh);page.addView(Ui.button(a,"Use BBC News feed",Ui.SURFACE,Ui.ACCENT,()->{sourceName.setText("BBC News");sourceUrl.setText("https://feeds.bbci.co.uk/news/rss.xml");}));page.addView(Ui.text(a,"Headlines are fetched from the feed you select when you press Refresh. Stories open at the source. No Apple News account is connected.",12,Ui.MUTED));}
        else if(kind.equals("stocks")){page.addView(Ui.text(a,"Connect your Alpha Vantage account. The provider's key, market coverage, plan and rate limits determine availability. Quotes show the provider's trading date and may be delayed. Nook does not supply an Apple Stocks account or investment advice.",12,Ui.MUTED));field(a,page,config,"symbol","Market symbol",false,false,refresh);field(a,page,config,"marketKey","Alpha Vantage API key",false,true,refresh);}
        else if(kind.equals("service")){field(a,page,config,"serviceName","Widget family (Mail, Home, Find My…)",false,false,refresh);field(a,page,config,"cardTitle","Your card heading",false,false,refresh);field(a,page,config,"cardDetail","Your card description",false,false,refresh);for(int n=0;n<3;n++)field(a,page,config,"detail"+n,"Your detail "+(n+1),false,false,refresh);page.addView(Ui.button(a,"Choose the app this card opens",Ui.SURFACE,Ui.ACCENT,()->chooseApp(a,name->{ExtraData.put(config,"package0",name);refresh.run();})));page.addView(Ui.text(a,"Manual card or app shortcut. Nook cannot read private iCloud Mail, Find My, HomeKit, Wallet, SmartThings, or vendor account data through this template. Its source mode remains visible on the widget.",12,Ui.MUTED));}
        else if(kind.equals("screentime")){page.addView(Ui.button(a,"Connect usage access",Ui.SURFACE,Ui.ACCENT,()->a.startActivity(new Intent(android.provider.Settings.ACTION_USAGE_ACCESS_SETTINGS))));page.addView(Ui.text(a,"Shows Android-reported foreground app time. Usage data is read locally after you grant access.",12,Ui.MUTED));}
        else if(kind.equals("compass"))page.addView(Ui.text(a,"Tap the placed widget for a live magnetic reading. The widget retains the last reading and labels it as such. Measurements need a compatible sensor; no location permission is used.",12,Ui.MUTED));
        else if(kind.equals("recorder"))page.addView(Ui.text(a,"Microphone access is requested when you record. Recording stops and saves when you leave the recorder screen. Memos stay in Nook's private storage; tap Play last to listen.",12,Ui.MUTED));
        else if(kind.equals("translate"))field(a,page,config,"language","Target language code (e.g. en, hi, fr)",false,false,refresh);
        else if(kind.equals("breathing"))page.addView(Ui.text(a,"A foreground breathing guide. Choose Box, 4–7–8, or Steady in the layout selector. Stop the session whenever you prefer.",12,Ui.MUTED));
        else if(kind.equals("stopwatch"))page.addView(Ui.text(a,"Start, pause, resume, reset and record laps from the widget. Time uses the phone's monotonic clock. A restart pauses the saved session rather than inventing elapsed time.",12,Ui.MUTED));
    }
}
